/**
 * Pixel-art wave scene parts, copied verbatim (data only) from the user's
 * Claude Code pixel-waves theme (~/.claude/skills/pixel-waves/hooks/scene.js)
 * so the app has no runtime dependency on ~/.claude. scene.ts composes them
 * the way that theme's register.tsx does. Generated artwork: don't hand-edit.
 * Each part has drift timings (dur/dir/bob); the app draws the scene still (§14).
 */
export type ScenePart = { g: string; dur: number; dir: number; bob: number };

export interface SceneParts {
  /** Tile width in scene pixels. */
  tw: number;
  /** View height in scene pixels. */
  vh: number;
  clouds: { x0: number; dur: number; g: string }[];
  layers: ScenePart[];
  twinkles: [number, number][];
}

